python3 -c "
from fontTools.ttLib import TTFont
import os

font_paths = [
    '/Users/henry/Library/Fonts/PingFangSC-Regular.ttf',
    '/Users/henry/Library/Fonts/PingFangSC-Semibold.ttf'
]

for path in font_paths:
    try:
        if not os.path.exists(path):
            print(f'{path} does not exist')
            continue

        font = TTFont(path)
        # Check if U+4E00 (一) is in the cmap
        has_char = False
        for table in font['cmap'].tables:
            if 0x4E00 in table.cmap:
                has_char = True
                break
        print(f'{os.path.basename(path)}: Valid font, Contains U+4E00: {has_char}')
    except Exception as e:
        print(f'{os.path.basename(path)}: Error: {e}')
"
